const body = $input.first()?.json?.body || $input.first()?.json || {};
const ticketNumber = (body.ticket_number || '').trim();
const rawRating = parseInt(body.rating, 10);
const feedback = (body.feedback || '').replace(/'/g, "''").slice(0, 1000);

if (!ticketNumber) {
  return [{ json: { is_valid: false, error: 'ticket_number is required' } }];
}

if (isNaN(rawRating) || rawRating < 1 || rawRating > 5) {
  return [{ json: { is_valid: false, error: 'rating must be an integer between 1 and 5' } }];
}

return [{
  json: {
    is_valid: true,
    ticket_number: ticketNumber,
    rating: rawRating,
    feedback: feedback
  }
}];
